def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    extra_items = np.floor(remaining / item)
    return np.where(remaining >= 0, -extra_items, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_leftover = 5.0
    remaining = bins - item
    return np.where(remaining >= 0, -np.abs(remaining - target_leftover), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_utilization = 0.8
    fits = bins >= item
    ratios = np.where(fits, item / bins, 1.0)
    return np.where(fits, -np.abs(ratios - target_utilization), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
